(function(){
  if (window.__gravInstalled__) return;
  window.__gravInstalled__ = true;
  var canvas = document.getElementById('gravCanvas');
  var ctx = canvas.getContext('2d');
  var m1Slider = document.getElementById('m1Slider');
  var m1Val = document.getElementById('m1Val');
  var m2Slider = document.getElementById('m2Slider');
  var m2Val = document.getElementById('m2Val');
  var rSlider = document.getElementById('rSlider');
  var rVal = document.getElementById('rVal');
  var orbitChk = document.getElementById('orbitChk');
  var orbitVal = document.getElementById('orbitVal');
  var out = document.getElementById('gravOut');
  var playBtn = document.getElementById('playBtn');
  var G = 6.67e-11;
  var running = false, orbitAngle = 0, pulse = 0;
  window.simState = { m1: 50, m2: 50, r: 3, F: 0, vOrb: 0, orbit: false, running: false, angle: 0 };
  function compute(){
    var m1 = parseFloat(m1Slider.value), m2 = parseFloat(m2Slider.value), r = parseFloat(rSlider.value);
    var F = G * m1 * m2 / (r * r);
    var vOrb = Math.sqrt(G * m1 / r);
    var orbit = orbitChk.checked;
    window.simState.m1 = m1; window.simState.m2 = m2; window.simState.r = r;
    window.simState.F = F; window.simState.vOrb = vOrb; window.simState.orbit = orbit;
    return { m1: m1, m2: m2, r: r, F: F, vOrb: vOrb, orbit: orbit };
  }
  function arrow(x1, y1, x2, y2, color){
    var dx = x2 - x1, dy = y2 - y1;
    var len = Math.sqrt(dx * dx + dy * dy);
    if (len < 3) return;
    var ux = dx / len, uy = dy / len;
    var hlen = Math.max(8, Math.min(len - 3, 42));
    var hx = x1 + ux * hlen, hy = y1 + uy * hlen;
    ctx.strokeStyle = color; ctx.lineWidth = 3;
    ctx.beginPath(); ctx.moveTo(x1, y1); ctx.lineTo(hx, hy); ctx.stroke();
    var ah = 9;
    ctx.fillStyle = color;
    ctx.beginPath();
    ctx.moveTo(hx + ux * ah, hy + uy * ah);
    ctx.lineTo(hx - uy * ah + ux * 2, hy + ux * ah + uy * 2);
    ctx.lineTo(hx + uy * ah + ux * 2, hy - ux * ah + uy * 2);
    ctx.closePath(); ctx.fill();
  }
  function massDot(x, y, r, label, color){
    ctx.fillStyle = color;
    ctx.beginPath(); ctx.arc(x, y, r, 0, Math.PI * 2); ctx.fill();
    ctx.strokeStyle = '#0f172a'; ctx.lineWidth = 1.5;
    ctx.beginPath(); ctx.arc(x, y, r, 0, Math.PI * 2); ctx.stroke();
    ctx.fillStyle = '#fff'; ctx.font = 'bold 12px sans-serif';
    ctx.textAlign = 'center'; ctx.textBaseline = 'middle';
    ctx.fillText(label, x, y + 1);
  }
  function draw(){
    var p = compute();
    ctx.clearRect(0, 0, canvas.width, canvas.height);
    var CX = canvas.width / 2, CY = canvas.height / 2;
    var px1, py1, px2, py2;
    if (p.orbit) {
      px1 = CX; py1 = CY;
      px2 = CX + (p.r / 10) * (canvas.width * 0.40) * Math.cos(orbitAngle);
      py2 = CY + (p.r / 10) * (canvas.width * 0.40) * Math.sin(orbitAngle);
      ctx.strokeStyle = '#cbd5e1'; ctx.lineWidth = 1.5;
      ctx.setLineDash([6, 6]);
      ctx.beginPath();
      ctx.arc(px1, py1, (p.r / 10) * (canvas.width * 0.40), 0, Math.PI * 2);
      ctx.stroke();
      ctx.setLineDash([]);
    } else {
      var half = (p.r / 10) * (canvas.width * 0.34);
      px1 = CX - half; py1 = CY;
      px2 = CX + half; py2 = CY;
    }
    var r1 = Math.min(16 + p.m1 * 0.12, 34);
    var r2 = Math.min(16 + p.m2 * 0.12, 34);
    massDot(px1, py1, r1, 'm₁', '#dc2626');
    massDot(px2, py2, r2, 'm₂', '#2563eb');
    var dx = px2 - px1, dy = py2 - py1;
    var d = Math.sqrt(dx * dx + dy * dy);
    var ux = dx / d, uy = dy / d;
    var flen = Math.min(90, 12 + Math.log10(1 + p.F * 1e9) * 22);
    if (p.F < 1e-9) flen = 12;
    arrow(px1 + ux * r1, py1 + uy * r1, px1 + ux * (r1 + flen), py1 + uy * (r1 + flen), '#dc2626');
    arrow(px2 - ux * r2, py2 - uy * r2, px2 - ux * (r2 + flen), py2 - uy * (r2 + flen), '#2563eb');
    if (running && !p.orbit) {
      pulse += 0.04;
      var pt = (pulse % 2) / 2;
      var ppx = px1 + (px2 - px1) * pt, ppy = py1 + (py2 - py1) * pt;
      ctx.fillStyle = '#f59e0b';
      ctx.beginPath(); ctx.arc(ppx, ppy, 5, 0, Math.PI * 2); ctx.fill();
    }
    m1Val.textContent = p.m1;
    m2Val.textContent = p.m2;
    rVal.textContent = p.r.toFixed(1);
    orbitVal.textContent = p.orbit ? 'تشغيل' : 'إيقاف';
    var Fs = p.F < 1e-6 ? p.F.toExponential(1) : p.F.toFixed(1);
    out.textContent = 'F = ' + Fs + ' N' + (p.orbit ? ' | سرعة المدار v = ' + p.vOrb.toExponential(1) + ' m/s' : '');
    window.simState.angle = orbitAngle;
  }
  playBtn.addEventListener('click', function(){
    running = !running;
    window.simState.running = running;
    playBtn.textContent = running ? 'إيقاف' : 'تشغيل الحركة';
  });
  m1Slider.addEventListener('input', function(){});
  m2Slider.addEventListener('input', function(){});
  rSlider.addEventListener('input', function(){});
  orbitChk.addEventListener('change', function(){ orbitAngle = 0; });
  function fit(){ canvas.style.maxWidth = '100%'; }
  if (!window.__fitInstalled__) { fit(); window.addEventListener('resize', fit); window.__fitInstalled__ = true; }
  function loop(){
    var p = compute();
    if (running && p.orbit) { orbitAngle += 0.02; }
    draw();
    requestAnimationFrame(loop);
  }
  loop();
})();
